import sys

def multiply(a, b, n):
    return (a * b) % n

def inverse(a, n):
    m = n
    r1, r2, r3, r4 = 1, 0, 0, 1
    while a > 0 and n > 0:
        if n >= a:
            r3 -= r1 * (n // a)
            r4 -= r2 * (n // a)
            n %= a
        else:
            a, n = n, a
            r1, r3 = r3, r1
            r2, r4 = r4, r2
    if a == 0:
        return r3 % m if r3 >= 0 else m + (r3 % m)
    else:
        return r1 % m if r1 >= 0 else m + (r1 % m)

def main():
    P = 998244353
    input_line = sys.stdin.readline().strip()
    tokens = input_line.split()
    n = int(tokens[0])
    k = int(tokens[1])
    l = int(tokens[2])

    factArr = [1] * (2 * n + 2)
    for i in range(1, 2 * n + 2):
        factArr[i] = multiply(factArr[i - 1], i, P)

    oddFactArr = [1] * (n + 1)
    for i in range(1, n + 1):
        oddFactArr[i] = multiply(oddFactArr[i - 1], (2 * i - 1), P)

    segmentData = [[0] * (n + 1) for _ in range(2 * n + 2)]

    for r in range(1, 2 * n + 2):
        for segK in range(1, n + 1):
            if ((r % 2) != (segK % 2)) and (r - 1 >= segK) and (2 * n + 1 - r >= segK):
                numerator = multiply(factArr[r - 1], factArr[2 * n + 1 - r], P)
                numerator = multiply(numerator, oddFactArr[(r - segK - 1) // 2], P)
                numerator = multiply(numerator, oddFactArr[(2 * n + 1 - r - segK) // 2], P)

                denominator = multiply(factArr[r - segK - 1], factArr[2 * n + 1 - r - segK], P)
                denominator = multiply(denominator, factArr[segK], P)

                inv_denominator = inverse(multiply(denominator, oddFactArr[n], P), P)
                segmentData[r][segK] = multiply(numerator, inv_denominator, P)

    totalWaysCount = 0
    for r in range(1, 2 * n + 2):
        for kk in range(k, n + 1):
            totalWaysCount += segmentData[r][kk]
            totalWaysCount %= P

    totalWaysCount = multiply(totalWaysCount, l, P)
    totalWaysCount = multiply(totalWaysCount, inverse(2 * n + 1, P), P)

    print(totalWaysCount)

if __name__ == "__main__":
    main()

